package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Function;

import org.junit.jupiter.api.Test;

class NativeExecutionTestRetriesTest {

	@Test
	void stopsWhenTheExpectedCompiledRoutesAppear() throws InterruptedException {
		List<String> compiled = List.of("irKernelDistinct", "irAggregateParallel", "nestedLoop");
		List<String> interpreted = List.of("irKernelDistinctInterpreted", "irAggregateParallelInterpreted",
				"nestedLoop");
		AtomicInteger retries = new AtomicInteger();
		assertThat(NativeExecutionTestRetries.retryInterpreted(interpreted, () -> {
			retries.incrementAndGet();
			return compiled;
		}, Function.identity(), compiled)).isEqualTo(compiled);
		assertThat(retries.get()).isEqualTo(1);
	}

	@Test
	void checksTheRouteOnceAfterCompilationCompletes() throws InterruptedException {
		List<String> compiled = List.of("irKernelDistinctParallel");
		List<String> interpreted = List.of("irKernelDistinctParallelInterpreted");
		AtomicInteger retries = new AtomicInteger();
		assertThat(NativeExecutionTestRetries.retryInterpreted(interpreted, () -> {
			retries.incrementAndGet();
			return interpreted;
		}, Function.identity(), compiled)).isEqualTo(interpreted);
		assertThat(retries.get()).isEqualTo(1);
	}

	@Test
	void doesNotRetryDifferentRoutesOrAlreadyMatchingRoutes() throws InterruptedException {
		List<String> expected = List.of("irKernelDistinct", "irAggregateParallel");
		for (List<String> actual : List.of(expected, List.of("irKernelDistinctInterpreted", "irAggregateInterpreted"),
				List.of("irKernelDistinctInterpreted"))) {
			assertThat(NativeExecutionTestRetries.retryInterpreted(actual, () -> {
				throw new AssertionError("Unexpected retry for " + actual);
			}, Function.identity(), expected)).isEqualTo(actual);
		}
	}
}
